<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('tickets.view');$pdo=db();$user=current_user();$isAdmin=((string)$user['role']==='admin')||has_permission('settings.manage');$pageTitle='Centro de soporte';$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'all');$stage=(string)($_GET['stage']??'all');$priority=(string)($_GET['priority']??'all');$where=[];$params=[];if(!$isAdmin){$where[]='t.user_id=?';$params[]=(int)$user['id'];}if($q!==''){$where[]='(t.ticket_number LIKE ? OR t.subject LIKE ? OR u.name LIKE ? OR u.email LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}if($status!=='all'){$where[]='t.status=?';$params[]=$status;}if($stage!=='all'){$where[]='t.stage=?';$params[]=$stage;}if($priority!=='all'){$where[]='t.priority=?';$params[]=$priority;}$sql="SELECT t.*,u.name user_name,u.email user_email,a.name assigned_name FROM support_tickets t JOIN users u ON u.id=t.user_id LEFT JOIN users a ON a.id=t.assigned_to".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY FIELD(t.status,'open','pending','resolved','closed'),FIELD(t.priority,'urgent','high','normal','low'),t.updated_at DESC";$s=$pdo->prepare($sql);$s->execute($params);$tickets=$s->fetchAll();$kpi=['open'=>0,'urgent'=>0,'sla'=>0,'follow'=>0,'closed'=>0];foreach($tickets as$t){if(!in_array($t['status'],['closed','resolved'],true))$kpi['open']++;if($t['priority']==='urgent'&&!in_array($t['status'],['closed','resolved'],true))$kpi['urgent']++;if(!empty($t['sla_due_at'])&&strtotime($t['sla_due_at'])<time()&&!in_array($t['status'],['closed','resolved'],true))$kpi['sla']++;if(!empty($t['next_follow_up_at'])&&date('Y-m-d',strtotime($t['next_follow_up_at']))<=date('Y-m-d')&&!in_array($t['status'],['closed'],true))$kpi['follow']++;if($t['status']==='closed')$kpi['closed']++;}require __DIR__.'/includes/header.php';?>
<div class="project-hero compact"><div><span class="eyebrow">HELPDESK · SOPORTE</span><h2><?=$isAdmin?'Mesa de soporte y seguimiento':'Mis solicitudes de soporte'?></h2><p><?=$isAdmin?'Recibe, asigna, responde, controla SLA y sigue la ruta completa de cada ticket.':'Crea un ticket y sigue cada respuesta y cambio de estado desde un solo lugar.'?></p></div><a class="btn btn-primary" href="support_ticket_form.php">+ NUEVO TICKET</a></div>
<div class="helpdesk-kpis"><div class="helpdesk-card"><small>ABIERTOS</small><strong><?=$kpi['open']?></strong><span>Requieren atención</span></div><div class="helpdesk-card"><small>URGENTES</small><strong><?=$kpi['urgent']?></strong><span>Prioridad máxima</span></div><div class="helpdesk-card"><small>SLA VENCIDO</small><strong><?=$kpi['sla']?></strong><span>Fuera del tiempo objetivo</span></div><div class="helpdesk-card"><small>SEGUIMIENTO</small><strong><?=$kpi['follow']?></strong><span>Acción programada</span></div><div class="helpdesk-card"><small>CERRADOS</small><strong><?=$kpi['closed']?></strong><span>Casos finalizados</span></div></div>
<section class="panel"><div class="panel-header"><div><h2>Cola de tickets</h2><span class="table-sub">Cada caso conserva conversación, ruta, responsable, prioridad y próximos pasos.</span></div></div><div class="panel-body"><form class="filters-wide"><label>Buscar<input name="q" value="<?=e($q)?>" placeholder="Nº, asunto, usuario"></label><label>Estado<select name="status"><option value="all">Todos</option><?php foreach(['open'=>'Abiertos','pending'=>'Pendientes','resolved'=>'Resueltos','closed'=>'Cerrados'] as$k=>$v):?><option value="<?=$k?>" <?=$status===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Etapa<select name="stage"><option value="all">Todas</option><?php foreach(['new'=>'Nuevo','triage'=>'Clasificación','in_progress'=>'En trabajo','waiting_user'=>'Esperando usuario','waiting_internal'=>'Esperando interno','resolved'=>'Resuelto','closed'=>'Cerrado'] as$k=>$v):?><option value="<?=$k?>" <?=$stage===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Prioridad<select name="priority"><option value="all">Todas</option><?php foreach(['urgent'=>'Urgente','high'=>'Alta','normal'=>'Normal','low'=>'Baja'] as$k=>$v):?><option value="<?=$k?>" <?=$priority===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><button class="btn btn-secondary">FILTRAR</button></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Ticket</th><th>Solicitante</th><th>Ruta</th><th>Responsable</th><th>SLA / seguimiento</th><th>Actualizado</th><th></th></tr></thead><tbody><?php if(!$tickets):?><tr><td colspan="7" class="empty">No hay tickets para mostrar.</td></tr><?php endif;?><?php foreach($tickets as$t):$slaLate=!empty($t['sla_due_at'])&&strtotime($t['sla_due_at'])<time()&&!in_array($t['status'],['closed','resolved'],true);?><tr><td><a class="table-title" href="support_ticket_view.php?id=<?=$t['id']?>"><?=e($t['ticket_number'])?> · <?=e($t['subject'])?></a><small class="table-sub"><span class="badge badge-<?=$t['priority']==='urgent'?'red':($t['priority']==='high'?'orange':'blue')?>"><?=e(crm_upper($t['priority']))?></span> · <?=e($t['department']?:'Soporte')?></small></td><td><strong><?=e($t['user_name'])?></strong><small class="table-sub"><?=e($t['user_email'])?></small></td><td><span class="ticket-stage <?=e($t['stage'])?>"><?=e(ucfirst(str_replace('_',' ',$t['stage'])))?></span></td><td><?=e($t['assigned_name']?:'Sin asignar')?></td><td><?php if($t['sla_due_at']):?><span class="badge <?=$slaLate?'badge-red':'badge-gray'?>">SLA <?=e(format_date_time($t['sla_due_at']))?></span><?php endif;?><?php if($t['next_follow_up_at']):?><small class="table-sub">Seguimiento: <?=e(format_date_time($t['next_follow_up_at']))?></small><?php endif;?></td><td><?=e(format_date_time($t['updated_at']))?></td><td><a class="btn btn-secondary btn-small" href="support_ticket_view.php?id=<?=$t['id']?>">ABRIR CASO →</a></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/includes/footer.php';?>
